import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for TokenBuffer.writeNumber(String)
 */
public class TokenBuffer_writeNumber_TriageGen0Test {

    private ObjectMapper mapper;
    private TokenBuffer tokenBuffer;

    @Before
    public void setUp() {
        mapper = new ObjectMapper();
        tokenBuffer = new TokenBuffer(mapper);
    }

    @Test
    public void testWriteNumber_IntegerString() throws IOException {
        String encodedValue = "123";
        tokenBuffer.writeNumber(encodedValue);

        Assert.assertEquals(JsonToken.VALUE_NUMBER_FLOAT, tokenBuffer.firstToken());

        // Verify content by serializing to string
        String result = tokenBuffer.toString();
        Assert.assertTrue(result.contains("123"));
    }














}

